//! The header of constants that opens the `.inc`, as a format string:
//! [`emit`](super::emit) fills it, each `{name}` with its named argument.
//! A macro and not a `const`, because `format!` takes only a literal.

#[rustfmt::skip]
macro_rules! header {
    () => { concat!(
    "; Generated by tools/port/snes_convert.py. Do not edit.\n",
    "; Maps: {maps}\n",
    "\n",
    "MAP_COUNT    = {map_count}\n",
    "MAP_STRIDE   = {map_stride}\n",
    "MAP_INITIAL = {map_initial}\n",
    "; What doesn't depend on the map: the upper layer's tilemap always\n",
    "; lives in the same place in VRAM —the background's is chosen by the\n",
    "; layout, M_VRAM_MAP—, and the NPC table's stride doesn't change.\n",
    "VRAM_ABOVE_MAP = ${vram_above_map:04X}\n",
    "MAP_LAYOUT  = {map_layout}\n",
    "NPC_STRIDE  = {npc_stride}\n",
    "NPC_MAX     = {npc_max}\n",
    "NPC_STILL   = ${npc_still:02X}\n",
    "; The event position table, and how many forced routes can be\n",
    "; running on them at once.\n",
    "EV_STRIDE   = {ev_stride}\n",
    "EV_MAX      = {ev_max}\n",
    "; The twins behind the positions: see `ev_pos_bytes`.\n",
    "TWIN_STRIDE = {twin_stride}\n",
    "ROUTE_EV_MAX = {route_ev_max}\n",
    "PAGE_BYTES = {page_bytes}\n",
    "TURN_NONE = ${turn_none:04X}\n",
    "; And how many distinct graphics command 34 asks for in the map of\n",
    "; this cartridge that asks for most: each map's table is copied to\n",
    "; far RAM, which is sized by it.\n",
    "ROUTE_GFX_MAX = {route_gfx_max}\n",
    "; The header of a text box, which is the first byte of the one\n",
    "; `OP_MESSAGE` names: the lines in the low three bits, the\n",
    "; auto-close of `\\^` in bit 3 and how many `\\|` pauses it carries in\n",
    "; the high nibble. And how long each pause lasts, which is 61 frames\n",
    "; and not 60: see PAUSE_FRAMES in events.py.\n",
    "HEADER_LINES        = ${header_lines:02X}\n",
    "HEADER_AUTOCLOSE = ${header_autoclose:02X}\n",
    "PAUSE_FRAMES        = {pause_frames}\n",
    "; The top bit of the flags byte of the opcodes that write a\n",
    "; variable: whether the write asks for the page refresh. The\n",
    "; converter resolves it by looking at which variables this map's\n",
    "; page conditions look at; `var_apuntar` masks the slot with\n",
    "; VAR_SLOT. See VAR_REFRESH in events.py: without this half of\n",
    "; Lashe City ran at 30 frames.\n",
    "VAR_REFRESH = ${var_refresh:02X}\n",
    "VAR_SLOT     = ${var_slot:02X}\n",
    "ANIM_ENTRY = {anim_entry}\n",
    "ANIM_SOUND   = {anim_sound}\n",
    "ANIM_FLASH = {anim_flash}\n",
    "; The flags of `KeyInputProc`, which go in the second byte of\n",
    "; OP_KEY. See `op_key` in rom/src/interpreter_keys_and_waits.s.\n",
    "KEY_WAIT       = ${key_wait:02X}\n",
    "KEY_DIRS       = ${key_dirs:02X}\n",
    "KEY_DECISION = ${key_decision:02X}\n",
    "KEY_CANCEL = ${key_cancel:02X}\n",
    "KEY_STARTS     = ${key_starts:02X}\n",
    "KEY_VALUE_DECISION = {key_value_decision}\n",
    "KEY_VALUE_CANCEL = {key_value_cancel}\n",
    "; And the four directions, with the same number `CheckInput` gives\n",
    "; them. The order they are checked in comes from here: from highest\n",
    "; to lowest, which is what \"RPG processes keys from highest\n",
    "; variable value to lowest\" says.\n",
    "KEY_VALUE_UP         = {key_value_up}\n",
    "KEY_VALUE_RIGHT      = {key_value_right}\n",
    "KEY_VALUE_LEFT = {key_value_left}\n",
    "KEY_VALUE_DOWN       = {key_value_down}\n",
    "; The ShowPicture pictures' objects: how many tiles of the name grid\n",
    "; have to be skipped to go from one object to the next, and from a\n",
    "; row of four to the following one. Each map's pictures are in\n",
    "; `picture_maps`.\n",
    "PICTURE_OBJ_STRIDE = {picture_obj_stride}\n",
    "PICTURE_ROW_STRIDE = {picture_row_stride}\n",
    "; The rain: see OP_WEATHER in events.py.\n",
    "RAIN_DROPS_MAX = {rain_drops_max}\n",
    "RAIN_DROPS_0 = {rain_drops_0}\n",
    "RAIN_DROPS_1 = {rain_drops_1}\n",
    "RAIN_DROPS_2 = {rain_drops_2}\n",
    "RAIN_LIFE     = {rain_life}\n",
    "RAIN_BORN     = {rain_born}\n",
    "RAIN_SEED = ${rain_seed:04X}\n",
    "WEATHER_RAIN  = {weather_rain}\n",
    "; And the sandstorm's type: see sandstorm.s.\n",
    "WEATHER_SAND  = {weather_sand}\n",
    "; The inventory: one byte per item of the LDB and RM2k's cap. See\n",
    "; OP_ITEM in events.py.\n",
    "ITEMS_N       = {items_n}\n",
    "ITEM_MAX      = {item_max}\n",
    "; The variables: how many slots this ROM carries —at least one,\n",
    "; because a zero length would close the save table—, the ControlVars\n",
    "; operand classes the ROM distinguishes, the sum, and the random\n",
    "; seed. See 'RM2k's variables' in events.py.\n",
    "VARIABLES_N   = {variables_n}\n",
    "VAR_ADD       = {var_add}\n",
    "VAR_VARIABLE  = {var_variable}\n",
    "VAR_RANDOM    = {var_random}\n",
    "VAR_OTHER     = {var_other}\n",
    "; Class 6, a character's coordinates: the target goes like that of\n",
    "; OP_ROUTE —0 the hero, the event's index plus one— and the other\n",
    "; operand says which coordinate. See VAR_CHARACTER in events.py.\n",
    "VAR_CHARACTER = {var_character}\n",
    "CHARACTER_X   = {character_x}\n",
    "CHARACTER_Y   = {character_y}\n",
    "; Class 5, an actor's HP, SP or their maximums: `a` is the actor and\n",
    "; `b` which. See VAR_ACTOR in events.py.\n",
    "VAR_ACTOR     = {var_actor}\n",
    "; The high bits of each OP_CELL_TEST write. See CELL_Y in\n",
    "; events.py.\n",
    "CELL_Y        = ${cell_y:04X}\n",
    "CELL_REFRESH = ${cell_refresh:04X}\n",
    "RANDOM_SEED   = ${random_seed:04X}\n",
    "; And the one for the encounters' randomness, which is a different\n",
    "; one on purpose: walking doesn't advance the map's randomness. See\n",
    "; ENC_SEED in events.py.\n",
    "ENC_SEED      = ${enc_seed:04X}\n",
    "TIMER_SET_VAR = {timer_set_var}\n",
    "TIMER_SLOT    = ${timer_slot:02X}\n",
    "; The ConditionalBranch condition classes we know, with the RM2k\n",
    "; number as is.\n",
    "COND_TIMER  = {cond_timer}\n",
    "COND_GOLD   = {cond_gold}\n",
    "COND_ITEM   = {cond_item}\n",
    "COND_ACTOR  = {cond_actor}\n",
    "; And the actor questions that carry two operands, with their\n",
    "; own opcode: see OP_IF_ACTOR in the events compiler.\n",
    "COND_ACTOR_SKILL = {cond_actor_skill}\n",
    "COND_ACTOR_EQUIPMENT = {cond_actor_equipment}\n",
    "COND_ACTOR_HP = {cond_actor_hp}\n",
    "COND_ACTOR_STATE = {cond_actor_state}\n",
    "GOLD_MAX    = {gold_max}\n",
    "; PanScreen's four operations.\n",
    "PAN_LOCK    = {pan_lock}\n",
    "PAN_UNLOCK  = {pan_unlock}\n",
    "PAN_RUN     = {pan_run}\n",
    "PAN_RETURN  = {pan_return}\n",
    "; The three timer operations.\n",
    "TIMER_SET      = {timer_set}\n",
    "TIMER_START = {timer_start}\n",
    "; And its five glyphs on screen: where the first goes and how wide\n",
    "; each one is. The colon's is number 10.\n",
    "TIMER_X        = {timer_x}\n",
    "TIMER_Y        = {timer_y}\n",
    "TIMER_GLYPH_W  = {timer_glyph_w}\n",
    "TIMER_TWO_POINTS = {timer_two_points}\n",
    "; How many frames fit in a second, and the extra ones `SetTimer`\n",
    "; adds so that the first second shows whole.\n",
    "TIMER_FRAMES   = {timer_frames}\n",
    "MORE_TIMER     = {more_timer}\n",
    "; How many flashes can be running at once.\n",
    "FLASH_MAX   = {flash_max}\n",
    "; How many events with a parallel page there can be in a map.\n",
    "PARALLEL_MAX = {parallel_max}\n",
    "TRIGGER_AUTO = {trigger_auto}\n",
    "TRIGGER_ACTION     = {trigger_action}\n",
    "TRIGGER_TOUCHES_HERO = {trigger_touches_hero}\n",
    "; The event's touch: the hero touching it, or it walking into him.\n",
    "TRIGGER_COLLISION  = {trigger_collision}\n",
    "TRIGGER_PARALLEL   = {trigger_parallel}\n",
    "; How many frames a one-cell step lasts. It comes from events.py and\n",
    "; not from a computation in the ROM.\n",
    "FRAMES_PER_CELL = {frames_per_cell}\n",
    "; A route's highest frequency, which is where commands 30 and 31\n",
    "; cap. The lowest is capped by the ROM at 1, like RM2k; what\n",
    "; guarantees it isn't reached is the converter, which rejects the\n",
    "; route.\n",
    "ROUTE_FREQUENCY = {route_frequency}\n",
    "; And how much a `wait` inside a forced route costs. **It isn't one\n",
    "; frame**: in RM2k it is `SetMaxStopCountForWait`, that is\n",
    "; `20 + (1 << (8 - frecuencia))`, and with frequency 8 —the only\n",
    "; one the converter lets through— it is twenty.\n",
    "ROUTE_WAIT = {route_wait}\n",
    "; And the jump: how much is left when it starts. How much it drops\n",
    "; per frame depends on the speed —`jump_per_speed`— and not on the\n",
    "; distance.\n",
    "JUMP_STEP = {jump_step}\n",
    "TINT_NEUTRAL = {tint_neutral}\n",
    "; The teleport fade: the ticks from the jump's, which already\n",
    "; darkens, to the first live one, and of those the ramp is 24 going\n",
    "; down and 24 going up. The map is loaded on tick {fade_load_tick}, in the black.\n",
    "; These numbers and the table below come from the fade constants of\n",
    "; tools/port/events.py.\n",
    "FADE_TOTAL      = {fade_total}\n",
    "FADE_RAMP       = {fade_ramp}\n",
    "FADE_LOAD       = {fade_load}\n",
    "BRIGHTNESS_MAX  = {brightness_max}\n",
    "; The teleport transitions the ROM does with the mosaic and with\n",
    "; the cut; any other is the fade. See `ChangeScreenTransitions` in\n",
    "; tools/port/events.py.\n",
    "TRANSITION_MOSAIC = {transition_mosaic}\n",
    "TRANSITION_CUTOFF  = {transition_cutoff}\n",
    "; The Y'CbCr luminance weights, which are the ones RM2k saturates\n",
    "; with. They add up to exactly 65536, so over five-bit channels they\n",
    "; give a five-bit luminance without rescaling anything.\n",
    "LIGHT_R = {light_r}\n",
    "LIGHT_G = {light_g}\n",
    "LIGHT_B = {light_b}\n",
    "; One bit per switch, up to the highest the game names.\n",
    "SWITCH_BYTES = {switch_bytes}\n",
    "; The party the game starts with, and its cap. In RM2k the hero's\n",
    "; graphic is the first one's, so this decides which sprite is\n",
    "; drawn; `ChangePartyMembers` moves it on the fly.\n",
    "PARTY_MAX      = {party_max}\n",
    "PARTY_INITIAL_N = {party_initial_n}\n",
    "ACTOR_BYTES    = {actor_bytes}\n",
    "; How many bytes of that entry are the actor's fifteen colors: the\n",
    "; ROM uploads them to the slot the leaders share. See\n",
    "; `pick_hero_graphic`.\n",
    "ACTOR_COLORS   = {actor_colors}\n",
    "OBJ_COLORS     = {obj_colors}\n",
    "; The hero's layer, to sort it against the NPCs.\n",
    "HERO_LAYER  = {hero_layer}\n",
    "; Its object priority. $10 —below the upper layer— in every ROM\n",
    "; other than `encima`'s, which raises it to $20 to exercise priority\n",
    "; 2. No event of the game gets to exercise it: see `test_encima` in\n",
    "; test_caminar_golden.py.\n",
    "HERO_PRIORITY = ${hero_priority:02X}\n",
    "; An event's object priority by its page's layer —above the hero, or\n",
    "; any other—, which an NPC row's attributes already carry: the page\n",
    "; of a walking row sets it from these. See `page_graphic`.\n",
    "LAYER_ABOVE = {layer_above}\n",
    "NPC_PRIORITY = ${npc_priority:02X}\n",
    "NPC_PRIORITY_ABOVE = ${npc_priority_above:02X}\n",
    "; The message window: its tiles live in the second half of the BG2\n",
    "; bank, that is from index 256, and its cells already come built\n",
    "; with that shift and with the upper layer's priority.\n",
    "; And where the background starts in CGRAM: below it live the\n",
    "; screen's backdrop color and the message window's palette, which\n",
    "; belong to the whole ROM. The background goes at 8 bits and\n",
    "; addresses CGRAM directly, so it is enough for it to start shifted.\n",
    "CGRAM_BASE     = {cgram_base}\n",
    "WINDOW_CGADD   = {window_cgadd}\n",
    "WINDOW_TILES   = {window_tiles}\n",
    "WINDOW_ROWS_ = {window_rows_}\n",
    "TEXT_WINDOW_COLS = {text_window_cols}\n",
    "; The text area: where it starts in the window's tile bank and\n",
    "; which cells it takes. Its tiles aren't deduplicated —the ROM\n",
    "; rewrites them— and that is where the width of a line, in\n",
    "; pixels, comes from.\n",
    "WINDOW_TEXT_BASE = {window_text_base}\n",
    "WINDOW_TEXT_ROW = {window_text_row}\n",
    "WINDOW_TEXT_ROWS = {window_text_rows}\n",
    "WINDOW_TEXT_COL    = {window_text_col}\n",
    "WINDOW_TEXT_COLS = {window_text_cols}\n",
    "MESSAGE_WIDTH  = {message_width}\n",
    "; The font: 96 glyphs of eight bits by twelve rows —ASCII and the\n",
    "; cursor's blank—, each with its advance, and the\n",
    "; shadow's palette index. That of each row of the glyph is in\n",
    "; font_color.\n",
    "FONT_HEIGHT    = {font_height}\n",
    "FONT_WIDTH     = {font_width}\n",
    "FONT_SHADOW    = {font_shadow}\n",
    "FONT_PRE_ROWS = {font_pre_rows}\n",
    "FONT_PRE_CHAR    = {font_pre_char}\n",
    "; A `ShowChoice`'s options go this many pixels further in than the\n",
    "; text, and the highlighted one is composed over `window_bar`.\n",
    "CHOICE_INDENT  = {choice_indent}\n",
    "; A box's face, `ChangeFaceGraphic`'s: the text-area cells it takes\n",
    "; —six by six from this row, and from this column on the left or on\n",
    "; the right—, where the text starts with a face on the left, and where\n",
    "; it stops with one on the right. See the screens' `layout.rs` and the\n",
    "; runtime's message_face.s.\n",
    "MSG_FACE_ROW = {msg_face_row}\n",
    "MSG_FACE_COL_LEFT = {msg_face_col_left}\n",
    "MSG_FACE_COL_RIGHT = {msg_face_col_right}\n",
    "MSG_FACE_TEXT_X = {msg_face_text_x}\n",
    "MSG_FACE_RIGHT_X = {msg_face_right_x}\n",
    "; The arrow of a message waiting for a key: the cells of the\n",
    "; window's tilemap it takes, and `window_arrow_cells` what goes\n",
    "; there.\n",
    "WINDOW_ARROW_ROW = {window_arrow_row}\n",
    "WINDOW_ARROW_COL = {window_arrow_col}\n",
    "WINDOW_ARROW_CELLS = {window_arrow_cells}\n",
    "; The ChipSet animation. Each map has an entry in `anim_table` with\n",
    "; its two runs and a block with the drawings; see `anim_table` in\n",
    "; snes_convert.py. The cadences and the water cycle come from\n",
    "; `rm2k.py`.\n",
    "ANIM_FAMILIES  = {anim_families}\n",
    "ANIM_STRIDE    = {anim_stride}\n",
    "ANIM_FAM_STRIDE = {anim_fam_stride}\n",
    "WATER_FRAMES   = {water_frames}\n",
    "WATER_DRAWINGS = {water_drawings}\n",
    "WATER_CYCLE_N  = {water_cycle_n}\n",
    "ANIMATED_FRAMES = {animated_frames}\n",
    "ANIMATED_STEPS = {animated_steps}\n",
    "BYTES_PER_TILE = {bytes_per_tile}\n",
    "; The title screen. TITLE_TILES at 0 means this ROM doesn't carry\n",
    "; it and the blocks below are one byte of padding; the code in\n",
    "; rom/src/ turns itself off with that. It lives alone in VRAM —it\n",
    "; shares with no map, because while it is shown there is no map\n",
    "; loaded— so its addresses are fixed and don't come from the\n",
    "; `vram_layout` layout. The image is uploaded by `screen_upload`,\n",
    "; from its row in `screens_table`: the tiles from $0000 and the\n",
    "; tilemap at SCREEN_MAP.\n",
    "TITLE_TILES    = {title_tiles}\n",
    "; Its bits per pixel: 8, on BG1 in mode 3 with all of CGRAM; or 4,\n",
    "; on BG1 in mode 1 with palettes 1 to 7, when its tiles at 8 don't\n",
    "; fit below the menu's tilemap. Then they take half: 897 at most,\n",
    "; every cell of the screen distinct and the blank one, $3810 words.\n",
    "TITLE_BPP      = {title_bpp}\n",
    "; The menu, on BG2 at four bits per pixel: its tile bank and how many\n",
    "; options it has. The cursor isn't drawn separately: there is one\n",
    "; tilemap per option, TITLE_MENU_N without a save and as many with\n",
    "; one after them, and moving it is uploading the other.\n",
    ";\n",
    "; The VRAM layout on this screen, in words, and why each one is\n",
    "; where it is: the image tiles start at 0 and end below $4400, so\n",
    "; everything else goes **above** that. A BG's tile base goes in\n",
    "; steps of 4096 words, which is what fixes $5000 for the menu; the\n",
    "; tilemaps go in steps of 1024 and fit in the gap next to it.\n",
    ";\n",
    ";   $0000 .. $4400   the image's tiles: 544 at 8bpp, or 897 at 4bpp\n",
    ";   $4400 .. $4800   the menu's tilemap\n",
    ";   $5000 ..         the menu's tiles, at 4bpp\n",
    ";   $7C00 .. $8000   the image's, SCREEN_MAP of game_over.s\n",
    "TITLE_MENU_CGRAM = {title_menu_cgram}\n",
    "TITLE_MENU_TILES = {title_menu_tiles}\n",
    "TITLE_MENU_VRAM   = $5000\n",
    "TITLE_MENU_MAP    = $4400\n",
    "TITLE_MENU_N      = {title_menu_n}\n",
    "; The slots screen, which both ends use: 'Resume the Story' and the\n",
    "; save point. It is a screen of its own —not a layer over the\n",
    "; title— so it is uploaded whole on entering. **It goes in every\n",
    "; ROM**, with a title or without: the save point opens it from\n",
    "; inside the game, and that is why its VRAM addresses are its own\n",
    "; and not the menu's: they fall in the BG1 tile bank of every\n",
    "; layout, which is what `back_to_map` restores with `load_map`.\n",
    "; See SLOT_MAP in the converter.\n",
    "SLOT_VRAM         = ${slot_vram:04X}\n",
    "SLOT_MAP          = ${slot_map:04X}\n",
    ";\n",
    "; The cell blocks: the header has two variants —load and save— and\n",
    "; each slot four —empty or full, with cursor or without—. Moving the\n",
    "; cursor is rewriting two rows and not a whole tilemap.\n",
    "SRAM_SLOTS_N      = {sram_slots_n}\n",
    "SLOT_TILES        = {slot_tiles}\n",
    "; How many of them, from the first, the menu and the actor choice\n",
    "; show: their composed names start after these. All of them unless\n",
    "; the bank had to put the slot screen's text last to make room.\n",
    "SLOT_MENU_TILES   = {slot_menu_tiles}\n",
    "; And where the slot screen composes its leaders' names: from the\n",
    "; first even tile at or after the first, and short of the end. After\n",
    "; the whole bank, unless each screen's text went apart: then over\n",
    "; the menu's text, which the slot screen does not show.\n",
    "SLOT_NAMES_FIRST  = {slot_names_first}\n",
    "SLOT_NAMES_END    = {slot_names_end}\n",
    "SLOT_HDR_ROW      = {slot_hdr_row}\n",
    "SLOT_HDR_ROWS     = {slot_hdr_rows}\n",
    "SLOT_HDR_CELLS = {slot_hdr_cells}\n",
    "SLOT_ROW0         = {slot_row0}\n",
    "SLOT_JUMP         = {slot_jump}\n",
    "SLOT_ROWS         = {slot_rows}\n",
    "SLOT_CELLS        = {slot_cells}\n",
    "; And where each row goes in the tilemap, in words. It also comes\n",
    "; from a table: the computation is SLOT_ROW0 + n * SLOT_JUMP,\n",
    "; times 32, and writing it in the 65816 would be the fourth place to\n",
    "; get it wrong.\n",
    "SLOT_HDR_VRAM     = {slot_hdr_vram}\n",
    "; How many blocks there are before the first of the rows: they are\n",
    "; the two headers, load and save.\n",
    "SLOT_BLOCK_ROWS = 2\n",
    "; The saved game's party, above the row: the faces of up to\n",
    "; SLOT_FACES_MAX, of SLOT_FACE_COLS by SLOT_FACE_ROWS cells,\n",
    "; and the first one's name and level. Which face block each actor\n",
    "; gets is said by `slot_face_block`, by actor id up to\n",
    "; SLOT_ACTORS_N, with $FF for 'has none'; and where they go,\n",
    "; `slot_face_vram` —four per slot— and `slot_name_vram`.\n",
    ";\n",
    "; The name and the level aren't blocks: they are composed one letter\n",
    "; per cell with `slot_glyph_cells`, and each actor's text comes\n",
    "; from its row of `slot_actor_text` —the name, the two digits of\n",
    "; the level and max HP, one after the other—. See 'what depends on\n",
    "; the actor' in rm2k-snes-screens: it is what keeps the tile bank\n",
    "; from growing with the number of actors.\n",
    "SLOT_FACES_MAX    = {slot_faces_max}\n",
    "SLOT_FACE_COLS    = {slot_face_cols}\n",
    "SLOT_FACE_ROWS = {slot_face_rows}\n",
    "SLOT_NAME_COLS      = {slot_name_cols}\n",
    "; How long an actor's row is in `slot_actor_text` and where each\n",
    "; strip starts inside it. The width is a power of two even if bytes\n",
    "; are left over: that way the index comes from shifts and not from a\n",
    "; multiplication.\n",
    "SLOT_TEXT_WIDTH     = {slot_text_width}\n",
    "SLOT_TEXT_NAME = 0\n",
    "SLOT_TEXT_LEVEL     = {slot_text_level}\n",
    "SLOT_TEXT_MAX       = {slot_text_max}\n",
    "SLOT_LEVEL_DIGITS = {slot_level_digits}\n",
    "; How many cells from the name the first digit of the level falls.\n",
    "SLOT_LEVEL_OFS      = {slot_level_ofs}\n",
    "; And where digit 0 starts inside `slot_glyph_cells`, which is\n",
    "; indexed by character: it is where the gold and the HP get their\n",
    "; digits from.\n",
    "GLYPH_DIGIT_0     = {glyph_digit_0}\n",
    "SLOT_ACTORS_N     = {slot_actors_n}\n",
    "; How many CGRAM entries the slots screen uploads: palette 0 for\n",
    "; the text and one per face, of sixteen each.\n",
    "SLOT_CGRAM_N      = {slot_cgram_n}\n",
    "; How many CGRAM entries the title menu uses: one palette of\n",
    "; sixteen, number 0. It is already defined above, with the title\n",
    "; screen; this confirms both computations give the same.\n",
    ".assert TITLE_MENU_CGRAM = {title_menu_cgram_again}, error, \"two computations of the menu's CGRAM\"\n",
    "\n",
    ) };
}
pub(super) use header;
